async function resumoProgressoRemessaV362DomainV45(env, remessaId) {
  const id = Math.max(0, Number(remessaId) || 0);
  if (!id) return null;
  const setores = ["CAD/CAM", "FATIAMENTO", "IMPRESSAO", "ACABAMENTO"];
  const resultado = {
    total: 0,
    setores: {}
  };
  const totalRow = await env.db.prepare(`
    SELECT COUNT(*) AS total
    FROM trabalhos t
    WHERE t.remessa_id = ?
      AND t.excluido = 0
  `).bind(id).first();
  resultado.total = Number(totalRow?.total || 0);
  for (const setor of setores) {
    const row = await env.db.prepare(`
      SELECT
        SUM(
          CASE
            WHEN EXISTS (
              SELECT 1
              FROM etapas e1
              WHERE e1.trabalho_id = t.id
                AND e1.setor = ?
            )
            AND NOT EXISTS (
              SELECT 1
              FROM etapas e2
              WHERE e2.trabalho_id = t.id
                AND e2.setor = ?
                AND e2.status != 'CONCLUIDO'
            )
            THEN 1
            ELSE 0
          END
        ) AS concluidos
      FROM trabalhos t
      WHERE t.remessa_id = ?
        AND t.excluido = 0
    `).bind(setor, setor, id).first();
    const concluidos = Number(row?.concluidos || 0);
    resultado.setores[setor] = {
      concluidos,
      faltam: Math.max(0, resultado.total - concluidos)
    };
  }
  return resultado;
}
