  const termo = `%${String(busca || "").trim().toLowerCase()}%`;
  const filtroRemessa = Number(remessaId || 0) ? "AND t.remessa_id = ?" : "";
  const filtroBusca = String(busca || "").trim() ? `
    AND (
      lower(t.paciente) LIKE ?
      OR lower(t.codigo) LIKE ?
      OR lower(t.municipio) LIKE ?
    )
  ` : "";
