    const dias = ajuste ? Number(ajuste.dias_considerados || 0) : detalhe.dias.size;
    const metaPeriodo = Number(regra.meta_diaria || 0) * dias;
    const excedente = Math.max(0, detalhe.quantidade - metaPeriodo);
