    const total = (area === "CONVENCIONAL" ? 0 : Number(remessa.digital_total || 0)) + (area === "DIGITAL" ? 0 : Number(remessa.convencional_total || 0));
    const prontos = (area === "CONVENCIONAL" ? 0 : Number(remessa.digital_prontos || 0)) + (area === "DIGITAL" ? 0 : Number(remessa.convencional_prontos || 0));
    const percentual = total > 0 ? Math.min(100, Math.round(prontos / total * 100)) : 0;
