async function listarFuncionarios(env) {
  const resultado = await env.db.prepare(`

      SELECT
        id,
        nome,
        usuario,
        setor,
        area_producao,
        setor_convencional,
        ativo

      FROM usuarios

      WHERE
        perfil = 'FUNCIONARIO'
        AND excluido = 0

      ORDER BY
        ativo DESC,
        nome ASC

    `).all();
  return resultado.results || [];
}
