async function gerarCodigoTrabalho(env) {
  const partes = new Intl.DateTimeFormat("en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).formatToParts(/* @__PURE__ */ new Date());
  const mapa = {};
  for (const parte of partes) mapa[parte.type] = parte.value;
  const prefixo = `FL-${mapa.year}${mapa.month}${mapa.day}-`;
  const row = await env.db.prepare(`
    SELECT COALESCE(MAX(CAST(substr(codigo, ?) AS INTEGER)), 0) AS maior
    FROM trabalhos
    WHERE codigo LIKE ?
      AND substr(codigo, ?) NOT GLOB '*[^0-9]*'
  `).bind(prefixo.length + 1, `${prefixo}%`, prefixo.length + 1).first();
  const proximo = Math.max(0, Number(row?.maior || 0)) + 1;
  return `${prefixo}${String(proximo).padStart(3, "0")}`;
}
async function criarEtapasDoTrabalho(env, trabalhoId, superiorTipo, inferiorTipo) {
  const agora = (/* @__PURE__ */ new Date()).toISOString();
  for (const [
    arcada,
    tipo
  ] of [
    [
      "SUPERIOR",
      superiorTipo
    ],
    [
      "INFERIOR",
      inferiorTipo
    ]
  ]) {
    if (tipo === "NONE") {
      continue;
    }
    for (const setor of SETORES) {
      await env.db.prepare(`

        INSERT INTO etapas (

          trabalho_id,
          setor,
          arcada,
          tipo_protese,
          status,
          responsavel_id,
          recebido_em,
          iniciado_em,
          concluido_em,
          conferido_por,
          conferido_em,
          retrabalhos

        )

        VALUES (

          ?,
          ?,
          ?,
          ?,
          'AGUARDANDO',
          NULL,
          ?,
          NULL,
          NULL,
          NULL,
          NULL,
          0

        )

      `).bind(
        trabalhoId,
        setor,
        arcada,
        tipo,
        setor === "CAD/CAM" ? agora : null
      ).run();
    }
    const componentes = tipo === "PT" || tipo === "TOTAL" ? [
      "BASE",
      "DENTES",
      "GENGIVA"
    ] : [
      "PPR_FLEX"
    ];
    for (const componente of componentes) {
      await env.db.prepare(`

        INSERT OR IGNORE
        INTO componentes_impressao (

          trabalho_id,
          arcada,
          componente,
          status,
          recebido_em

        )

        VALUES (
          ?,
          ?,
          ?,
          'AGUARDANDO',
          NULL
        )

      `).bind(
        trabalhoId,
        arcada,
        componente
      ).run();
    }
  }
}
function nomeSituacao(situacao) {
  const nomes = {
    ENTREGUE: "Entregue",
    CONCLUIDO: "Concluído",
    EM_PRODUCAO: "Em produção",
    PENDENCIA: "Retrabalho",
    AGUARDANDO: "Aguardando"
  };
  return nomes[situacao] || situacao;
}
function classeSituacao(situacao) {
  if (situacao === "ENTREGUE" || situacao === "CONCLUIDO") {
    return "ok";
  }
  if (situacao === "EM_PRODUCAO") {
    return "andamento";
  }
  if (situacao === "PENDENCIA") {
    return "alerta";
  }
  return "neutro";
}
