function formularioResponsavelProjetoConcluidoV3417(usuario, etapa, responsaveisProjetos = []) {
  if (!isAdmin(usuario) || etapa.setor !== "CAD/CAM" || etapa.status !== "CONCLUIDO") {
    return "";
  }
  const atualId = Number(etapa.responsavel_id || 0);
  const opcoes = (responsaveisProjetos || []).map((funcionario) => `
      <option value="${Number(funcionario.id)}" ${Number(funcionario.id) === atualId ? "selected" : ""}>
        ${escapeHtml(funcionario.nome)}
      </option>
    `).join("");
  if (!opcoes) {
    return `<div class="aviso" style="margin-top:10px">Nenhum funcionário ativo de CAD/CAM disponível para correção do responsável.</div>`;
  }
  return `
    <details style="margin-top:12px;border-top:1px solid var(--borda);padding-top:10px">
      <summary style="cursor:pointer;font-weight:700">✎ Alterar responsável pelo projeto concluído</summary>
      <form method="POST" action="/etapas/${Number(etapa.id)}/responsavel-projeto" style="margin-top:10px">
        <label>
          Responsável correto
          <select name="responsavel_id" required>
            <option value="">Selecione</option>
            ${opcoes}
          </select>
        </label>
        <label style="margin-top:8px">
          Motivo / observação
          <input name="motivo" maxlength="250" placeholder="Ex.: projeto concluído pelo funcionário correto">
        </label>
        <button class="botao-sec botao-bloco" style="margin-top:8px" type="submit">Salvar correção</button>
        <div class="mini" style="margin-top:7px">A conclusão e o horário original são preservados. Apenas o responsável pela produção é corrigido e a alteração fica registrada no histórico.</div>
      </form>
    </details>
  `;
}
function formularioDesfazerConclusaoAcabamentoV351(usuario, etapa) {
  if (!isCoord(usuario) || etapa.setor !== "ACABAMENTO" || etapa.status !== "CONCLUIDO" || !etapa.concluido_em) {
    return "";
  }
  return `
    <details style="margin-top:12px;border-top:1px solid var(--borda);padding-top:10px">
      <summary style="cursor:pointer;font-weight:700;color:#f0b429">↶ Desfazer conclusão registrada por engano</summary>
      <form method="POST" action="/etapas/${Number(etapa.id)}/desfazer-conclusao-acabamento" style="margin-top:10px" onsubmit="return confirm('Desfazer a conclusão deste Acabamento? A etapa voltará para Em andamento.');">
        <label>
          Motivo obrigatório
          <input name="motivo" minlength="5" maxlength="250" required placeholder="Ex.: conclusão registrada por engano">
        </label>
        <button class="botao-alerta botao-bloco" style="margin-top:8px" type="submit">Desfazer conclusão</button>
        <div class="mini" style="margin-top:7px">Mantém o responsável e o início da etapa. Somente a conclusão é removida e a correção fica registrada no histórico.</div>
      </form>
    </details>
  `;
}
function cardEtapaFichaV3417(usuario, etapa, responsaveisProjetos = []) {
  const html = cardProducaoV336(usuario, etapa, "etapas");
  const extras = [
    formularioResponsavelProjetoConcluidoV3417(
      usuario,
      etapa,
      responsaveisProjetos
    ),
    formularioDesfazerConclusaoAcabamentoV351(usuario, etapa)
  ].filter(Boolean).join("");
  if (!extras) return html;
  const fim = html.lastIndexOf("</div>");
  if (fim < 0) return html + extras;
  return html.slice(0, fim) + extras + html.slice(fim);
}
