async function obterRetencao(env) {
  const resultado = await env.db.prepare(`

      SELECT

        t.id,
        t.codigo,
        t.municipio,
        t.paciente,
        t.data_entrega,
        t.arquivado,
        t.retencao_adiada_ate,

        CAST(
          (
            julianday('now')
            -
            julianday(
              t.data_entrega
            )
          )
          AS INTEGER
        )
        AS dias,

        CASE

          WHEN
            date(
              t.data_entrega,
              '+6 months'
            )
            <=
            date('now')

          THEN 1

          ELSE 0

        END
        AS pode_excluir

      FROM trabalhos t

      WHERE
        t.excluido = 0

        AND t.entregue = 1

        AND t.data_entrega
          IS NOT NULL

        AND date(
          t.data_entrega,
          '+4 months'
        )
        <=
        date('now')

        AND (

          t.retencao_adiada_ate
            IS NULL

          OR

          date(
            t.retencao_adiada_ate
          )
          <=
          date('now')
        )

      ORDER BY
        t.municipio,
        t.data_entrega

    `).all();
  return resultado.results || [];
}
