async function listarRetrabalhosSetorConvencional(env, setor, busca = "") {
  const q = String(busca || "").trim().toLowerCase();
  const termo = `%${q}%`;
  const filtro = q ? `
    AND (
      lower(t.paciente) LIKE ? OR
      lower(t.municipio) LIKE ? OR
      CAST(t.numero_articulador AS TEXT) LIKE ?
    )
  ` : "";
  let stmt = env.db.prepare(`
    SELECT
      r.*,
      p.arcada,
      p.tipo_protese,
      t.numero_articulador,
      t.paciente,
      t.municipio,
      t.uf,
      u.nome AS responsavel_nome,
      iq.criado_em AS reprovado_em,
      q.nome AS qualidade_responsavel_nome
    FROM retrabalhos_convencionais r
    INNER JOIN pecas_convencionais p ON p.id = r.peca_id
    INNER JOIN trabalhos_convencionais t ON t.id = r.trabalho_id
    LEFT JOIN usuarios u ON u.id = r.responsavel_id
    LEFT JOIN inspecoes_qualidade_convencional iq ON iq.id = r.inspecao_id
    LEFT JOIN usuarios q ON q.id = iq.responsavel_id
    WHERE r.setor_retorno = ?
      AND r.status IN ('AGUARDANDO','EM_ANDAMENTO')
      AND t.excluido = 0
      ${filtro}
    ORDER BY CASE r.status WHEN 'EM_ANDAMENTO' THEN 1 ELSE 2 END, r.id ASC
    LIMIT 500
  `);
  stmt = q ? stmt.bind(setor, termo, termo, termo) : stmt.bind(setor);
  const resultado = await stmt.all();
  return resultado.results || [];
}
