async function dadosIntegridadeV30(env) {
  const [tipos, qualidade, semPecas, cargasVazias, remessas] = await Promise.all([
    env.db.prepare(`
      SELECT
        p.id AS peca_id,
        p.arcada,
        p.tipo_protese,
        t.id AS trabalho_id,
        t.numero_articulador,
        t.paciente,
        t.municipio
      FROM pecas_convencionais p
      INNER JOIN trabalhos_convencionais t ON t.id = p.trabalho_id
      WHERE t.excluido = 0
        AND (p.tipo_protese IS NULL OR p.tipo_protese NOT IN ('PT','PPR'))
      ORDER BY t.ciclo_id DESC, t.numero_articulador ASC, p.arcada ASC
      LIMIT 200
    `).all(),
    env.db.prepare(`
      SELECT
        p.id AS peca_id,
        p.arcada,
        t.id AS trabalho_id,
        t.numero_articulador,
        t.paciente,
        t.municipio
      FROM pecas_convencionais p
      INNER JOIN trabalhos_convencionais t ON t.id = p.trabalho_id
      LEFT JOIN etapas_convencionais q
        ON q.peca_id = p.id AND q.setor = 'QUALIDADE'
      WHERE t.excluido = 0
        AND q.id IS NULL
      ORDER BY t.ciclo_id DESC, t.numero_articulador ASC
      LIMIT 200
    `).all(),
    env.db.prepare(`
      SELECT t.id AS trabalho_id, t.numero_articulador, t.paciente, t.municipio
      FROM trabalhos_convencionais t
      LEFT JOIN pecas_convencionais p ON p.trabalho_id = t.id
      WHERE t.excluido = 0
      GROUP BY t.id
      HAVING COUNT(p.id) = 0
      ORDER BY t.ciclo_id DESC, t.numero_articulador ASC
      LIMIT 100
    `).all(),
    env.db.prepare(`
      SELECT c.id, c.numero_mufla, c.status, c.criado_em
      FROM cargas_muflas_convencionais c
      LEFT JOIN muflas_convencionais m
        ON m.carga_id = c.id AND m.ativo = 1
      WHERE c.ativo = 1
      GROUP BY c.id
      HAVING COUNT(m.id) = 0
      ORDER BY c.numero_mufla ASC
      LIMIT 100
    `).all(),
    env.db.prepare(`
      SELECT
        r.id,
        r.municipio,
        r.numero,
        r.data_finalizacao,
        r.data_entrega_real,
        CASE WHEN r.data_entrega_real IS NOT NULL AND r.data_finalizacao IS NULL THEN 1 ELSE 0 END AS entrega_sem_finalizacao,
        CASE WHEN EXISTS (
          SELECT 1
          FROM trabalhos t
          WHERE t.remessa_id = r.id
            AND t.excluido = 0
            AND EXISTS (
              SELECT 1 FROM etapas e
              WHERE e.trabalho_id = t.id AND e.status != 'CONCLUIDO'
            )
        ) THEN 1 ELSE 0 END AS digital_pendente,
        CASE WHEN EXISTS (
          SELECT 1
          FROM trabalhos_convencionais tc
          WHERE tc.remessa_id = r.id
            AND tc.excluido = 0
            AND tc.status NOT IN ('LIBERADO_ENTREGA','CONCLUIDO')
        ) THEN 1 ELSE 0 END AS convencional_pendente
      FROM remessas r
      WHERE
        (r.data_entrega_real IS NOT NULL AND r.data_finalizacao IS NULL)
        OR (
          r.data_finalizacao IS NOT NULL
          AND (
            EXISTS (
              SELECT 1 FROM trabalhos t
              WHERE t.remessa_id = r.id
                AND t.excluido = 0
                AND EXISTS (
                  SELECT 1 FROM etapas e
                  WHERE e.trabalho_id = t.id AND e.status != 'CONCLUIDO'
                )
            )
            OR EXISTS (
              SELECT 1 FROM trabalhos_convencionais tc
              WHERE tc.remessa_id = r.id
                AND tc.excluido = 0
                AND tc.status NOT IN ('LIBERADO_ENTREGA','CONCLUIDO')
            )
          )
        )
      ORDER BY r.municipio ASC, r.numero ASC
      LIMIT 100
    `).all()
  ]);
  const dados = {
    tipos_invalidos: tipos.results || [],
    sem_qualidade: qualidade.results || [],
    trabalhos_sem_pecas: semPecas.results || [],
    cargas_vazias: cargasVazias.results || [],
    remessas_inconsistentes: remessas.results || []
  };
  dados.total_problemas = Object.values(dados).reduce((soma, lista) => soma + (Array.isArray(lista) ? lista.length : 0), 0);
  return dados;
}
