function extensaoArquivoImportacaoV330(nome) {
  const limpo = String(nome || "").trim().toLowerCase();
  const pos = limpo.lastIndexOf(".");
  if (pos < 0) return "";
  return limpo.slice(pos);
}
function mimeArquivoImportacaoV330(nome) {
  return TIPOS_ARQUIVO_IMPORTACAO_V330[extensaoArquivoImportacaoV330(nome)] || null;
}
function nomeArquivoImportacaoV330(nome) {
  return String(nome || "arquivo").replace(/[\r\n\t]/g, " ").replace(/\s+/g, " ").trim().slice(0, 220) || "arquivo";
}
function statusImportacaoNomeV330(status) {
  const mapa = {
    RASCUNHO: "Rascunho",
    PROCESSANDO: "Processando",
    REVISAO: "Em revisão",
    PRONTO: "Pronto para confirmar",
    CONFIRMADO: "Confirmado",
    CANCELADO: "Cancelado",
    ERRO: "Erro"
  };
  return mapa[String(status || "").toUpperCase()] || status || "—";
}
function classeImportacaoV330(status) {
  const s = String(status || "").toUpperCase();
  if (["CONFIRMADO", "PRONTO"].includes(s)) return "ok";
  if (["PROCESSANDO", "REVISAO"].includes(s)) return "andamento";
  if (s === "ERRO") return "perigo";
  if (s === "CANCELADO") return "neutro";
  return "alerta";
}
async function obterImportacaoFolhaV330(env, id) {
  return await env.db.prepare(`
    SELECT
      i.*,
      r.numero AS remessa_numero,
      r.data_recebimento AS remessa_recebimento,
      r.data_prevista_entrega AS remessa_previsao,
      r.data_finalizacao AS remessa_finalizacao,
      r.data_entrega_real AS remessa_entrega,
      r.ciclo_digital_id
    FROM importacoes_folhas_producao i
    LEFT JOIN remessas r ON r.id=i.remessa_id
    WHERE i.id=?
    LIMIT 1
  `).bind(Number(id || 0)).first();
}
async function listarImportacoesRemessaV330(env, remessaId) {
  const resultado = await env.db.prepare(`
    SELECT
      i.*,
      u.nome AS criador_nome,
      SUM(CASE WHEN img.id IS NOT NULL AND img.status!='EXCLUIDA' THEN 1 ELSE 0 END) AS total_arquivos,
      COALESCE(SUM(CASE WHEN img.status!='EXCLUIDA' THEN img.tamanho_bytes ELSE 0 END),0) AS total_bytes
    FROM importacoes_folhas_producao i
    LEFT JOIN usuarios u ON u.id=i.criado_por
    LEFT JOIN imagens_importacao_folhas img ON img.importacao_id=i.id
    WHERE i.area='DIGITAL'
      AND i.remessa_id=?
    GROUP BY i.id
    ORDER BY i.id DESC
    LIMIT 30
  `).bind(Number(remessaId || 0)).all();
  return resultado.results || [];
}
async function listarArquivosImportacaoV330(env, importacaoId) {
  const resultado = await env.db.prepare(`
    SELECT *
    FROM imagens_importacao_folhas
    WHERE importacao_id=?
      AND status!='EXCLUIDA'
    ORDER BY ordem ASC, id ASC
  `).bind(Number(importacaoId || 0)).all();
  return resultado.results || [];
}
