function cardResumoMaterialV36(item) {
  const embalagens = Number(item.embalagens || 0);
  const pacientes = Number(item.pacientes || 0);
  const proteses = Number(item.proteses || 0);
  const rendimento = embalagens > 0 ? proteses / embalagens : 0;
  const mediaFisica = proteses > 0 && Number(item.lancamentos_com_conteudo || 0) > 0 ? Number(item.quantidade_fisica || 0) / proteses : null;
  const custoMedio = proteses > 0 && Number(item.lancamentos_com_custo || 0) > 0 ? Math.round(Number(item.custo_centavos || 0) / proteses) : null;
  const embalagem = String(item.embalagem || item.embalagem_atual || "embalagem");
  const unidade = String(item.unidade_medida || item.unidade_atual || "");
  return `
    <article class="card" style="padding:14px">
      <div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start;flex-wrap:wrap">
        <div><span class="mini">${escapeHtml(rotuloCategoriaMaterialV36(item.categoria))}</span><h3 style="margin:3px 0 0">${escapeHtml(item.nome)}</h3></div>
        <span class="badge andamento">${numeroMaterialV36(embalagens)} ${escapeHtml(embalagem)}${embalagens === 1 ? "" : "(s)"}</span>
      </div>
      <div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px">
        <div><span class="mini">Pacientes vinculados</span><strong style="display:block;font-size:24px">${pacientes}</strong></div>
        <div><span class="mini">Próteses / arcadas</span><strong style="display:block;font-size:24px">${proteses}</strong></div>
        <div><span class="mini">Rendimento</span><strong style="display:block">${numeroMaterialV36(rendimento, 1)} próteses/${escapeHtml(embalagem)}</strong></div>
        <div><span class="mini">Média por prótese</span><strong style="display:block">${mediaFisica === null ? "—" : `${numeroMaterialV36(mediaFisica, 2)} ${escapeHtml(unidade)}`}</strong></div>
      </div>
      ${Number(item.lancamentos_com_conteudo || 0) > 0 ? `<p class="mini" style="margin:10px 0 0">Quantidade física usada: ${numeroMaterialV36(item.quantidade_fisica, 2)} ${escapeHtml(unidade)}.</p>` : `<p class="mini" style="margin:10px 0 0">Cadastre o conteúdo da embalagem para calcular g/ml por prótese.</p>`}
      ${custoMedio === null ? "" : `<p class="mini" style="margin:4px 0 0">Custo estimado: ${escapeHtml(formatarMoedaCentavosV25(Math.round(Number(item.custo_centavos || 0))))} · média ${escapeHtml(formatarMoedaCentavosV25(custoMedio))}/prótese.</p>`}
    </article>
  `;
}
